#!/usr/bin/env python3
"""Generate the static GitHub Pages dashboard (docs/index.html + docs/dashboard.json) from dashboard.json."""
import os, json
ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))

TEMPLATE = r"""<!doctype html>
<html lang="en"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="robots" content="noindex">
<title>Solana Paper Bot 2.0 — paper trading dashboard</title>
<style>
:root{--bg:#0f1115;--card:#181b22;--text:#e8eaf0;--muted:#9aa3b2;--line:#2a2f3a;--ok:#2fbf71;--warn:#f0b429;--bad:#ef4f4f;--accent:#7aa7ff}
@media (prefers-color-scheme: light){:root{--bg:#f6f7f9;--card:#fff;--text:#14171f;--muted:#5b6575;--line:#e2e5ea;--accent:#2457d6}}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;padding:env(safe-area-inset-top) 0 40px}
.wrap{max-width:980px;margin:0 auto;padding:12px}
.banner{background:var(--warn);color:#1b1400;font-weight:700;text-align:center;padding:10px;border-radius:10px;margin:8px 0 12px}
.stale{background:var(--bad);color:#fff;font-weight:600;padding:10px;border-radius:10px;margin-bottom:12px;display:none}
h1{font-size:22px;margin:4px 0}h2{font-size:17px;margin:22px 0 8px}
.sub{color:var(--muted);font-size:13px}
.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}@media(min-width:700px){.grid{grid-template-columns:repeat(4,1fr)}}
.m{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:10px}
.m .v{font-size:20px;font-weight:700}.m .l{color:var(--muted);font-size:12px}
.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:10px;overflow-x:auto;-webkit-overflow-scrolling:touch}
table{border-collapse:collapse;width:100%;font-size:13px;white-space:nowrap}th,td{padding:6px 8px;border-bottom:1px solid var(--line);text-align:left}
th{color:var(--muted);font-weight:600}td.n{text-align:right;font-variant-numeric:tabular-nums}
.pill{display:inline-block;padding:1px 8px;border-radius:99px;font-size:12px;font-weight:600}
.ok{background:rgba(47,191,113,.18);color:var(--ok)}.warn{background:rgba(240,180,41,.2);color:var(--warn)}.bad{background:rgba(239,79,79,.18);color:var(--bad)}
a{color:var(--accent);text-decoration:none}.mono{font-family:ui-monospace,Menlo,monospace;font-size:12px}
.pos{color:var(--ok)}.neg{color:var(--bad)}.empty{color:var(--muted);padding:6px}
dl{display:grid;grid-template-columns:auto 1fr;gap:4px 12px;margin:0}dt{color:var(--muted)}dd{margin:0}
</style></head><body><div class="wrap">
<div class="banner">PAPER TRADING ONLY — simulated $100 account. No wallet, no keys, no real transactions.</div>
<div class="stale" id="stale"></div>
<h1>Solana Paper Bot 2.0</h1>
<div class="sub" id="gen"></div>
<h2>Portfolio</h2><div class="grid" id="metrics"></div>
<h2>Run status</h2><div class="card"><dl id="status"></dl></div>
<h2>Open positions</h2><div class="card" id="open"></div>
<h2>Trade history</h2><div class="card" id="trades"></div>
<h2>Recent runs &amp; start delays</h2><div class="card" id="runs"></div>
<h2>Failed / skipped runs</h2><div class="card" id="problems"></div>
<h2>Recent errors</h2><div class="card" id="errors"></div>
<h2>Latest candidates</h2><div class="card" id="evals"></div>
<p class="sub">Data: DEX Screener (prices, pairs), GeckoTerminal (discovery), RugCheck (safety) — free public APIs. Generated by GitHub Actions; times shown in US Eastern.</p>
</div>
<script id="data" type="application/json">__DATA__</script>
<script>
const D=JSON.parse(document.getElementById('data').textContent);
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const usd=(v,d=2)=>v==null?'n/a':(v<0?'-':'')+'$'+Math.abs(v).toLocaleString('en-US',{minimumFractionDigits:d,maximumFractionDigits:d});
const px=v=>v==null?'n/a':'$'+Number(v).toPrecision(6);
const et=s=>{if(!s)return 'n/a';const d=new Date(s);return d.toLocaleString('en-US',{timeZone:'America/New_York',month:'short',day:'numeric',hour:'numeric',minute:'2-digit',second:'2-digit'})+' ET'};
const ago=s=>{const m=(Date.now()-new Date(s))/60000;return m<1?'just now':m<60?Math.round(m)+' min ago':(m/60).toFixed(1)+' h ago'};
const short=a=>a?esc(a.slice(0,4)+'…'+a.slice(-4)):'';
const pill=(t,c)=>`<span class="pill ${c}">${esc(t)}</span>`;
const st=s=>pill(s,s==='ok'?'ok':(s==='skipped_overlap'?'warn':'bad'));
const pl=v=>v==null?'':`<span class="${v>=0?'pos':'neg'}">${usd(v,4)}</span>`;
const table=(cols,rows,empty)=>rows.length?`<table><thead><tr>${cols.map(c=>`<th>${c}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.join('')}</tr>`).join('')}</tbody></table>`:`<div class="empty">${empty}</div>`;
const td=(v,n)=>`<td${n?' class="n"':''}>${v}</td>`;
const link=(u,t)=>u&&/^https?:/.test(u)?`<a href="${esc(u)}" target="_blank" rel="noopener">${t}</a>`:esc(t);
const tok=a=>link('https://dexscreener.com/solana/'+a,`<span class="mono">${short(a)}</span>`);
$('gen').textContent='Dashboard generated '+et(D.generated_at);
const ls=D.latest_scan&&D.latest_scan.ts;
if(!ls||(Date.now()-new Date(ls))>45*60000){const e=$('stale');e.style.display='block';e.textContent='STALE: latest scan was '+(ls?et(ls)+' ('+ago(ls)+')':'never')+'. Scheduled runs may be delayed or stopped.'}
const wr=D.win_rate_pct==null?'n/a':D.win_rate_pct.toFixed(1)+'%';
$('metrics').innerHTML=[[usd(D.portfolio_value_usd),'Portfolio value'],[usd(D.cash_usd),'Cash'],[D.open_positions.length+' / 3','Open positions'],[usd(D.realized_pnl_usd,4),'Realized P/L'],[usd(D.unrealized_pnl_usd,4),'Unrealized P/L'],[wr,'Win rate'],[String(D.closed_trades),'Closed trades ('+D.total_fills+' fills)'],[D.max_drawdown_pct.toFixed(2)+'%','Max drawdown'],[usd(D.total_fees_usd,4),'Fees (est.)'],[usd(D.total_slippage_usd,4),'Slippage (est.)'],[usd(D.total_pnl_usd,4),'Total P/L vs $100'],[String(D.runs_total),'Runs logged']].map(([v,l])=>`<div class="m"><div class="v">${v}</div><div class="l">${l}</div></div>`).join('');
const g=D.last_github_run;
const nxt=new Date(Math.ceil(Date.now()/900000)*900000);
$('status').innerHTML=[['Latest scan',ls?et(ls)+' ('+ago(ls)+')':'never'],['Tokens in latest scan',D.latest_scan?D.latest_scan.tokens_seen+' unique, '+D.latest_scan.candidates_passed_prefilter+' passed pre-filters':'n/a'],['Last GitHub run',g?st(g.status)+' '+esc(g.event||'')+' '+link(g.github_run_url,'#'+esc(g.github_run_id))+' · '+et(g.started_at):'none yet'],['Last start delay',g&&g.start_delay_sec!=null?Math.round(g.start_delay_sec/60*10)/10+' min after '+et(g.scheduled_for):'n/a (manual run)'],['Schedule',esc(D.schedule.cadence||D.schedule.note||'')],['Next nominal slot',et(nxt.toISOString())+' (GitHub may start it late)'],['Errors / skips logged',D.errors_count+' errors · '+D.skips_count+' skips']].map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('');
$('open').innerHTML=table(['Token','Mint','Entry time','Entry mid','Last price','Qty','Cost','Value','Unreal. P/L','Stop','Target','Source'],D.open_positions.map(p=>[td(esc(p.symbol)),td(tok(p.token_address)),td(et(p.entry_time)),td(px(p.entry_mid_price),1),td(px(p.last_price)+'<br><span class="sub">'+et(p.last_price_time)+'</span>',1),td(Number(p.qty).toPrecision(6),1),td(usd(p.cost_usd,4),1),td(usd(p.market_value_usd,4),1),td(pl(p.unrealized_pnl_usd),1),td(px(p.stop_price),1),td(px(p.target_price),1),td(link(p.source,'DEX Screener'))]),'No open positions.');
$('trades').innerHTML=table(['#','Time','Side','Token','Mint','Pair','Mid price','Fill price','Qty','Net USD','Fee','Slippage','Price fetched','Exit reason','P/L','Source'],D.trade_history.slice().reverse().map(t=>[td(t.id),td(et(t.ts)),td(pill(t.side,t.side==='BUY'?'ok':'warn')),td(esc(t.symbol)),td(tok(t.token_address)),td(`<span class="mono">${short(t.pair_address)}</span>`),td(px(t.mid_price),1),td(px(t.fill_price),1),td(Number(t.qty).toPrecision(6),1),td(usd(t.net_usd,4),1),td(usd(t.fee_usd,4),1),td(usd(t.slippage_usd,4),1),td(et(t.price_fetched_at)),td(esc(t.exit_reason||'')),td(pl(t.realized_pnl_usd),1),td(link(t.source_url,'source'))]),'No simulated trades yet — no candidate has met every entry rule.');
$('runs').innerHTML=table(['Run','Started','Status','Trigger','Event','Delay','GitHub'],D.recent_runs.map(r=>[td(r.id),td(et(r.started_at)),td(st(r.status)),td(esc(r.trigger)),td(esc(r.event||'')),td(r.start_delay_sec==null?'':(r.start_delay_sec/60).toFixed(1)+' min',1),td(r.github_run_url?link(r.github_run_url,'#'+esc(r.github_run_id)):'')]),'No runs.');
$('problems').innerHTML=table(['Run','Started','Status','Trigger','Detail'],D.problem_runs.map(r=>[td(r.id),td(et(r.started_at)),td(st(r.status)),td(esc(r.trigger)),td(esc((r.error_summary||'').slice(0,160))+(r.github_run_url?' '+link(r.github_run_url,'log'):''))]),'None.');
$('errors').innerHTML=table(['Time','Stage','Message'],D.recent_errors.map(e=>[td(et(e.ts)),td(esc(e.stage)),`<td style="white-space:normal">${esc(e.message.slice(0,240))}</td>`]),'None.');
const seen=new Set();
$('evals').innerHTML=table(['Token','Mint','Price','Liquidity','Safety','Score','Decision','Checked'],D.recent_evaluations.filter(e=>!seen.has(e.token_address)&&seen.add(e.token_address)).map(e=>[td(esc(e.symbol)),td(tok(e.token_address)),td(px(e.price_usd),1),td(usd(e.liquidity_usd,0),1),td(e.safety_passed?pill('pass','ok'):pill('reject','bad')),td(e.score==null?'–':e.score,1),td(esc(e.decision)),td(et(e.ts))]),'No candidates evaluated yet.');
</script></body></html>
"""

def main():
    d = json.load(open(os.path.join(ROOT, "dashboard.json")))
    os.makedirs(os.path.join(ROOT, "docs"), exist_ok=True)
    blob = json.dumps(d, default=str, separators=(",", ":")).replace("</", "<\\/")
    open(os.path.join(ROOT, "docs", "index.html"), "w").write(TEMPLATE.replace("__DATA__", blob))
    json.dump(d, open(os.path.join(ROOT, "docs", "dashboard.json"), "w"), indent=1, default=str)
    open(os.path.join(ROOT, "docs", ".nojekyll"), "w").write("")
    print("docs/index.html written,", len(blob), "bytes of data")

if __name__ == "__main__":
    main()
